import Image from "next/image";
import Link from "next/link";
import { MapPin, Clock, Phone, Mail, Globe, Star, ChevronDown } from "lucide-react";
import type { BusinessAdData } from "@/lib/validators/template-schemas";

interface BusinessProps { data: BusinessAdData; accentColor?: string; }
interface BizProps { data: BusinessAdData; accentColor?: string; }

// ─────────────────────────────────────────────────────────────────────────────
// SHARED HELPERS
// ─────────────────────────────────────────────────────────────────────────────

function contactHref(type: string, value: string) {
  if (type === "email") return `mailto:${value}`;
  if (type === "phone") return `tel:${value.replace(/\s/g, "")}`;
  if (type === "website") return value.startsWith("http") ? value : `https://${value}`;
  return "#";
}

function StarRating({ rating }: { rating: number }) {
  return (
    <div className="flex">
      {Array.from({ length: 5 }).map((_, i) => (
        <span key={i} className={i < rating ? "text-amber-400" : "text-neutral-700"}>★</span>
      ))}
    </div>
  );
}
export function DistrictBusiness({ data, accentColor = "#0284c7" }: BusinessProps) {
  const { businessName, tagline, description, logoUrl, heroImageUrl, services, contacts, testimonials, businessHours, faq, primaryCtaLabel, primaryCtaUrl, address, socialLinks } = data;

  return (
    <main className="min-h-screen bg-slate-50 text-slate-900">
      {/* Header */}
      <header className="sticky top-0 z-50 bg-white shadow-sm border-b border-slate-200">
        <div className="mx-auto max-w-5xl px-6 py-4 flex items-center justify-between">
          {logoUrl ? (
            <Image src={logoUrl} alt={businessName} width={120} height={40} className="h-10 w-auto object-contain" />
          ) : (
            <span className="text-lg font-black">{businessName}</span>
          )}
          <a href={primaryCtaUrl} className="rounded-lg px-4 py-2 text-sm font-semibold text-white" style={{ background: accentColor }}>
            {primaryCtaLabel}
          </a>
        </div>
      </header>

      {/* Hero */}
      <section className="relative overflow-hidden border-b border-slate-200">
        {heroImageUrl && (
          <div className="relative h-80">
            <Image src={heroImageUrl} alt={businessName} fill className="object-cover" sizes="100vw" priority />
            <div className="absolute inset-0 bg-slate-900/60" />
            <div className="absolute inset-0 flex flex-col items-center justify-center text-center px-6 text-white">
              <h1 className="text-4xl font-black md:text-5xl">{businessName}</h1>
              <p className="mt-3 text-lg text-white/80 max-w-md">{tagline}</p>
            </div>
          </div>
        )}
        {!heroImageUrl && (
          <div className="px-6 py-20 text-center" style={{ background: `linear-gradient(135deg, ${accentColor}15, ${accentColor}05)` }}>
            <h1 className="text-4xl font-black text-slate-900 md:text-5xl">{businessName}</h1>
            <p className="mt-3 text-lg text-slate-600 max-w-md mx-auto">{tagline}</p>
          </div>
        )}
      </section>

      {/* About */}
      <section className="border-b border-slate-200 bg-white px-6 py-14">
        <div className="mx-auto max-w-3xl text-center">
          <h2 className="text-2xl font-black mb-4">About Us</h2>
          <p className="leading-relaxed text-slate-600">{description}</p>
          {address && (
            <div className="mt-6 flex items-center justify-center gap-2 text-sm text-slate-500">
              <MapPin className="h-4 w-4 shrink-0" style={{ color: accentColor }} />
              {address.street}, {address.city}, {address.state} {address.postalCode}
            </div>
          )}
        </div>
      </section>

      {/* Services */}
      <section className="border-b border-slate-200 px-6 py-14">
        <div className="mx-auto max-w-5xl">
          <h2 className="mb-8 text-center text-2xl font-black">Our Services</h2>
          <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {services.map((s, i) => (
              <div key={i} className={`rounded-2xl p-5 ${s.highlighted ? "text-white shadow-lg" : "border border-slate-200 bg-white"}`}
                style={s.highlighted ? { background: accentColor } : {}}>
                <h3 className="font-bold text-lg">{s.title}</h3>
                {s.price && <p className="mt-1 text-2xl font-black">{s.price}</p>}
                <p className="mt-2 text-sm opacity-80">{s.description}</p>
                {s.features && (
                  <ul className="mt-3 space-y-1.5">
                    {s.features.map((f, j) => <li key={j} className="flex items-center gap-2 text-sm"><span className="font-bold">✓</span>{f}</li>)}
                  </ul>
                )}
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Hours + Contact */}
      <section className="border-b border-slate-200 bg-white px-6 py-14">
        <div className="mx-auto max-w-5xl grid gap-10 md:grid-cols-2">
          <div>
            <h2 className="mb-5 flex items-center gap-2 text-xl font-black"><Clock className="h-5 w-5" style={{ color: accentColor }} />Business Hours</h2>
            {businessHours && businessHours.length > 0 ? (
              <div className="space-y-2 divide-y divide-slate-100">
                {businessHours.map((h, i) => (
                  <div key={i} className="flex justify-between py-2 text-sm">
                    <span className="font-medium text-slate-700">{h.day}</span>
                    <span className="text-slate-500">{h.isClosed ? "Closed" : `${h.open} – ${h.close}`}</span>
                  </div>
                ))}
              </div>
            ) : <p className="text-slate-500 text-sm">Contact us for hours.</p>}
          </div>
          <div>
            <h2 className="mb-5 flex items-center gap-2 text-xl font-black"><Phone className="h-5 w-5" style={{ color: accentColor }} />Get in Touch</h2>
            <div className="space-y-3">
              {contacts.map((c, i) => (
                <a key={i} href={c.type === "email" ? `mailto:${c.value}` : c.type === "phone" ? `tel:${c.value}` : c.value}
                  className="flex items-center gap-3 rounded-lg border border-slate-200 px-4 py-3 text-sm hover:border-slate-300 hover:bg-slate-50 transition-all">
                  {c.type === "email" && <Mail className="h-4 w-4 shrink-0 text-slate-400" />}
                  {c.type === "phone" && <Phone className="h-4 w-4 shrink-0 text-slate-400" />}
                  {c.type === "website" && <Globe className="h-4 w-4 shrink-0 text-slate-400" />}
                  <span className="text-slate-700">{c.value}</span>
                </a>
              ))}
            </div>
          </div>
        </div>
      </section>

      {/* FAQ */}
      {faq && faq.length > 0 && (
        <section className="border-b border-slate-200 px-6 py-14">
          <div className="mx-auto max-w-3xl">
            <h2 className="mb-8 text-center text-2xl font-black">Frequently Asked Questions</h2>
            <div className="space-y-4">
              {faq.map((item, i) => (
                <details key={i} className="group rounded-xl border border-slate-200 bg-white">
                  <summary className="flex cursor-pointer items-center justify-between px-5 py-4 font-semibold text-slate-800">
                    {item.question}
                    <ChevronDown className="h-4 w-4 text-slate-400 transition-transform group-open:rotate-180" />
                  </summary>
                  <div className="border-t border-slate-100 px-5 py-4 text-sm leading-relaxed text-slate-600">
                    {item.answer}
                  </div>
                </details>
              ))}
            </div>
          </div>
        </section>
      )}

      {/* Testimonials */}
      {testimonials && testimonials.length > 0 && (
        <section className="bg-white border-b border-slate-200 px-6 py-14">
          <div className="mx-auto max-w-5xl">
            <h2 className="mb-8 text-center text-2xl font-black">What Our Clients Say</h2>
            <div className="grid gap-5 md:grid-cols-2 lg:grid-cols-3">
              {testimonials.slice(0, 6).map((t, i) => (
                <div key={i} className="rounded-xl border border-slate-200 p-5">
                  <div className="flex gap-1 mb-3">
                    {Array.from({ length: t.rating }).map((_, j) => <Star key={j} className="h-4 w-4 fill-current text-yellow-400" />)}
                  </div>
                  <p className="text-sm text-slate-600 italic">&ldquo;{t.text}&rdquo;</p>
                  <p className="mt-3 text-xs font-semibold text-slate-800">— {t.author}</p>
                  {t.platform && <p className="text-xs text-slate-400">{t.platform}</p>}
                </div>
              ))}
            </div>
          </div>
        </section>
      )}

      <footer className="px-6 py-8 border-t border-slate-200 bg-slate-50 flex flex-wrap gap-4 items-center justify-between">
        <div className="flex gap-4">
          {socialLinks.map((s, i) => <Link key={i} href={s.url} target="_blank" rel="noopener noreferrer" className="text-xs text-slate-500 hover:text-slate-900 transition-colors">{s.label ?? s.platform}</Link>)}
        </div>
        <p className="text-xs text-slate-400">PresenceCard</p>
      </footer>
    </main>
  );
}
